<script lang="ts">
 import Heading from '$lib/components/Heading.svelte';import Icon from '$lib/components/Icon.svelte';import {infraState,infraCommand,infraId} from '$lib/infra/store';
 let show=false,editing='',name='',schedule='0 4 * * *',command='',error='',notice='';
 function start(id=''){const job=$infraState.cron.find(x=>x.id===id);editing=id;name=job?.name||'';schedule=job?.schedule||'0 4 * * *';command=job?.command||'';show=true;error='';}
 function submit(){try{if(editing)infraCommand({type:'cron-edit',id:editing,name,schedule,command});else infraCommand({type:'cron-create',id:infraId(),name,schedule,command});notice=(editing?'Scheduled job updated.':'Job draft saved.')+' No system cron job was installed.';show=false;error='';}catch(e){error=e instanceof Error?e.message:'Invalid scheduled job.';}}
 function act(fn:()=>void){try{fn();error='';notice='Sample operation recorded. No command was executed.';}catch(e){error=e instanceof Error?e.message:'Action unavailable.';}}
 function remove(id:string){if(window.confirm('Delete this sample scheduled job?'))act(()=>infraCommand({type:'cron-delete',id}));}
</script>
<Heading title="Cron jobs" subtitle="Configure recurring server tasks; execution is disabled in this development preview."><button class="btn primary" on:click={()=>start()}><Icon name="Plus"/> New cron job</button></Heading>
<div class="stack"><div class="callout"><strong>Schedules and commands are demonstrations.</strong><p>These tasks are not installed into crontab and do not run on the VPS. Future production execution must be scoped to an authorized project or isolated worker.</p></div>
{#if show}<form class="card stack" on:submit|preventDefault={submit}><h3>{editing?'Edit scheduled job':'Create scheduled job'}</h3><div class="grid2"><label class="field">Job name<input bind:value={name} required maxlength="300" placeholder="Daily maintenance"/></label><label class="field">Cron expression<input bind:value={schedule} required maxlength="120" placeholder="0 4 * * *"/><small>minute hour day month weekday</small></label></div><label class="field">Command (sample only)<input bind:value={command} required maxlength="300" placeholder="php artisan schedule:run"/></label><small>New jobs are disabled by default. Nothing is executed or scheduled.</small>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="native-actions"><button class="btn secondary" type="button" on:click={()=>show=false}>Cancel</button><button class="btn primary" type="submit">Save job</button></div></form>{/if}
{#if !show&&error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="subtitle" role="status">{notice}</p>{/if}
<section class="card table-card"><div class="table-head"><h3>Scheduled jobs</h3></div><div class="table-wrap"><table><thead><tr><th>Job</th><th>Schedule</th><th>Enabled</th><th>Actions</th></tr></thead><tbody>{#each $infraState.cron as j (j.id)}<tr><td><strong>{j.name}</strong><small class="mono" style="display:block">{j.command}</small></td><td class="mono">{j.schedule}</td><td><label class="check"><input type="checkbox" checked={j.enabled} on:change={(e)=>act(()=>infraCommand({type:'cron-toggle',id:j.id,enabled:e.currentTarget.checked}))}/> {j.enabled?'On (demo)':'Off'}</label></td><td><div class="table-actions"><button class="btn secondary small" on:click={()=>act(()=>infraCommand({type:'cron-run',id:j.id}))}>Simulate run</button><button class="btn secondary small" on:click={()=>start(j.id)}>Edit</button><button class="btn danger small" on:click={()=>remove(j.id)}>Delete</button></div></td></tr>{:else}<tr><td colspan="4">No scheduled jobs configured.</td></tr>{/each}</tbody></table></div></section>
{#if $infraState.cron.some(j=>j.runs.length)}<section class="card"><h3>Recent simulated runs</h3>{#each $infraState.cron as j}{#each j.runs.slice(0,3) as run}<div class="setting-row"><div><strong>{j.name}</strong><small style="display:block">{run.label}</small></div><small>{new Date(run.at).toLocaleString()}</small></div>{/each}{/each}</section>{/if}
</div>
